<template>
  <main class="resource-page" v-loading="loading">
    <section class="resource-list">
      <header class="page-heading"><div><div class="eyebrow">系统管理 / {{ moduleTitle }}</div><h1>{{ moduleTitle }}</h1><p>{{ moduleDescription }}</p></div><el-button @click="router.push('/admin/reports/advice')">前往专家问策</el-button></header>
      <div v-if="error" class="notice error" role="alert">{{ error }} <el-button link @click="retryLoad">重新加载</el-button></div>
      <div class="relationship"><b>专家</b><span>调用</span><b>技能</b><span>使用</span><b>MCP 工具</b><small>{{ kind==='experts'?'先查看用途与可运行任务，再维护草稿和技能关联。':kind==='skills'?'独立维护处理方法、规则说明和输入输出。':'维护服务连接、工具及其使用关系。' }}</small></div>
      <div class="list-actions"><el-button type="primary" :disabled="busy" @click="startCreate()">{{ kind==='skills'?'导入技能包':`新增${kindLabel}` }}</el-button><el-button :disabled="busy" @click="showArchived=!showArchived;loadArchive()">{{ showArchived?'返回正常列表':'已删除资源' }}</el-button></div>
      <div class="toolbar"><el-input v-model="search" clearable placeholder="搜索名称、用途或编码" aria-label="搜索资源" /><el-select v-model="category" clearable placeholder="全部分类" aria-label="筛选分类"><el-option v-for="value in categories" :key="value" :label="value" :value="value" /></el-select><el-select v-model="status" clearable placeholder="全部状态" aria-label="筛选发布状态"><el-option label="已发布" value="published" /><el-option label="待发布" value="draft" /><el-option label="已停用" value="disabled" /></el-select><el-button @click="load">刷新</el-button><el-button @click="listView=!listView">{{ listView?'卡片视图':'列表视图' }}</el-button></div>
      <div class="category-chips"><button :class="{active:!category}" @click="category=''">全部 {{ catalog[kind].length }}</button><button v-for="value in categories" :key="value" :class="{active:category===value}" @click="category=value">{{ value }} {{ catalog[kind].filter(item=>item.category===value).length }}</button></div>
      <div class="resource-grid" :class="{'list-view':listView}">
        <article v-for="item in displayed" :key="item.id" class="resource-card"><div class="card-body"><div class="card-heading"><div class="resource-icon" aria-hidden="true">{{ item.draft.content.icon || (kind==='experts'?'🎓':kind==='skills'?'🧩':'🛠️') }}</div><h2>{{ item.name }}</h2></div><p>{{ item.summary || '尚未填写用途说明' }}</p><div class="tags"><span>{{ item.category || '通用' }}</span><span>{{ item.deletedAt?'已删除':!item.enabled?'已停用':item.published?`已发布 v${item.published.version}`:'尚未发布' }}</span><span v-if="item.published&&item.draft.version!==item.published.version">有新版本草稿</span><span v-if="kind==='experts'">{{ item.draft.content.skillIds?.length||0 }} 项技能</span><span v-else-if="kind==='skills'">{{ item.draft.content.toolBindings?.length||0 }} 项工具依赖</span><span v-else>{{ item.draft.content.tools?.length||0 }} 个工具</span></div><div class="card-readiness">{{ readiness(item) }}</div></div><footer><span>{{ item.id }}<small class="updated-at">{{ formatDate(item.updatedAt) }} · 北京时间</small></span><el-button v-if="item.deletedAt" :disabled="busy" @click="restoreResource(item)">恢复</el-button><el-button v-else type="primary" plain @click="open(item)">查看{{ kindLabel }}</el-button><el-dropdown v-if="!item.deletedAt" trigger="click" @command="command=>cardAction(String(command),item)"><el-button aria-label="更多维护操作">···</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="test">{{ kind==='mcps'?'连接测试':'测试草稿' }}</el-dropdown-item><el-dropdown-item v-if="kind==='experts'&&item.published&&item.enabled" command="use">验证已发布能力</el-dropdown-item><el-dropdown-item command="copy">复制为草稿</el-dropdown-item><el-dropdown-item command="references">查看使用关系</el-dropdown-item><el-dropdown-item command="delete" divided>删除</el-dropdown-item></el-dropdown-menu></template></el-dropdown></footer></article>
      </div><el-empty v-if="!loading&&!displayed.length" description="没有符合条件的资源" />
      <p class="page-note">资源配置与会话记录保存在本地；业务数据来自114测试环境数据库，只读查询。</p>
    </section>
    <el-drawer :model-value="!!selected&&!createVisible&&!importVisible" class="resource-detail-drawer" direction="rtl" :size="expanded?'100vw':'min(980px,94vw)'" :close-on-click-modal="true" :before-close="closeDetail" destroy-on-close>
      <template #header><div class="drawer-heading"><div><span class="eyebrow">{{ kindLabel }}详情</span><h2>{{ selected?.name }}</h2></div><el-button :disabled="busy" @click="expanded=!expanded">{{ expanded?'收起为侧栏':'展开全屏' }}</el-button></div></template>
      <template v-if="selected">
      <button v-if="navigation.length||route.query.backTo" class="back-link" @click="back">← {{ typeof route.query.backLabel==='string'?`返回${route.query.backLabel}`:navigation.length?`返回${navigation[navigation.length-1].name}`:`返回${kindLabel}列表` }}</button>
      <header class="page-heading"><div><div class="eyebrow">{{ kindLabel }} / {{ selected.id }}</div><p>{{ selected.summary||'尚未填写用途说明' }}</p><p class="version-context">现行 {{ selected.published?`v${selected.published.version}`:'尚未发布' }} · 草稿 v{{ selected.draft.version }} / 修订 {{ selected.draft.revision }}</p></div><div class="heading-actions"><span v-if="editing" class="muted">正在编辑草稿</span><el-button v-else type="primary" :disabled="busy" @click="startEdit">编辑草稿</el-button><el-dropdown :disabled="busy||dirty" trigger="click" @command="detailAction"><el-button :disabled="busy||dirty">更多操作</el-button><template #dropdown><el-dropdown-menu><el-dropdown-item command="copy">复制为草稿</el-dropdown-item><el-dropdown-item v-if="selected.published?.version===selected.draft.version" command="new">新建版本草稿</el-dropdown-item><el-dropdown-item command="toggle">{{ selected.enabled?'停用资源':'启用资源' }}</el-dropdown-item><el-dropdown-item command="delete" divided>删除</el-dropdown-item></el-dropdown-menu></template></el-dropdown></div></header>
      <div v-if="error" class="notice error" role="alert">{{ error }} <el-button link :disabled="busy" @click="reloadSelected">重新加载</el-button></div>
      <div class="version-bar"><template v-if="section!=='test'&&section!=='presets'"><el-radio-group v-if="selected.published&&!editing" v-model="viewVersion"><el-radio-button value="published">现行发布版本</el-radio-button><el-radio-button value="draft">草稿预览</el-radio-button></el-radio-group><span v-else>{{ editing?'正在编辑草稿':'草稿预览，尚未生效' }}</span></template><span v-else>{{ section==='test'?`验证草稿 v${selected.draft.version} · 修订 ${selected.draft.revision}`:'预设任务使用实际发布版本' }}</span><small>{{ dirty?'有未保存修改':viewVersion==='published'&&!editing?'现行内容只读；修改请编辑草稿。':'草稿保存后需测试与发布才会生效。' }}</small></div>
      <nav class="resource-tabs" aria-label="配置分区"><button :class="{active:section==='basic'}" @click="section='basic'">{{ kind==='experts'?'能力概览':kind==='skills'?'用途、步骤与规则':'连接与工具' }}</button><button :class="{active:section==='dependencies'}" @click="section='dependencies'">{{ kind==='experts'?'技能与依赖':kind==='skills'?'输入输出与依赖':'使用关系' }}</button><button v-if="kind==='experts'" :class="{active:section==='presets'}" @click="section='presets'">预设任务</button><button :class="{active:section==='test'}" @click="section='test'">{{ kind==='mcps'?'连接测试与发布':'草稿测试与发布' }}</button></nav>
      <section v-if="section==='basic'&&!editing&&kind!=='mcps'" class="binding-summary">
        <div class="section-heading"><h2>{{ kind==='experts'?'已绑定技能':'MCP工具依赖' }}</h2><el-button :disabled="busy" @click="editBindings">{{ kind==='experts'?'修改技能绑定':'修改工具关联' }}</el-button></div>
        <div class="tags"><span v-for="name in bindingNames" :key="name">{{ name }}</span><span v-if="!bindingNames.length">暂无关联</span></div>
        <p class="muted">{{ kind==='experts'?'专家选择技能；MCP工具由技能自动带出。修改技能后保存草稿，测试并发布才生效。':'在技能中维护调用的MCP服务与工具。关联必须与已登记的实际方法一致。' }}</p>
        <el-button link @click="section='dependencies'">{{ kind==='experts'?'查看技能及MCP工具关系':'查看输入输出及工具关系' }}</el-button>
      </section>
      <div v-if="section==='basic'" class="editor-body">
        <template v-if="editing"><div class="form-grid"><label class="field"><span>名称 *</span><el-input v-model="content.name" maxlength="80" /></label><label class="field"><span>类型分类</span><el-select v-model="content.category" filterable allow-create default-first-option clearable placeholder="选择或填写分类"><el-option v-for="value in sharedCategories" :key="value" :label="value" :value="value" /></el-select></label><label class="field"><span>应用编码（创建后不可改）</span><el-input :model-value="selected.id" disabled /></label><label class="field full"><span>用途说明</span><el-input v-model="content.summary" type="textarea" :autosize="{minRows:2,maxRows:6}" /></label><label v-if="kind!=='mcps'" class="field full"><span>{{ kind==='experts'?'处理与结果说明要求':'执行说明' }}</span><el-input v-model="content.instructions" type="textarea" :autosize="{minRows:3,maxRows:10}" /><small>文字说明不会自动改变已登记查询与算法。</small></label></div>
          <ResourceConfiguration v-if="kind!=='skills'" v-model="content" :kind="kind" :resource-id="selected.id" :experts="catalog.experts" :skills="catalog.skills" :mcps="catalog.mcps" />
          <template v-if="kind==='experts'"><EditableLines title="具体职责" :model-value="content.responsibilities||[]" @update:model-value="content.responsibilities=$event" /><EditableLines title="适用边界" :model-value="content.boundaries||[]" @update:model-value="content.boundaries=$event" /><EditableLines title="示例问题" :model-value="content.starterQuestions||[]" @update:model-value="content.starterQuestions=$event" /><p class="notice">技能关联统一在“技能与依赖”中维护。模型人设仅在模型运行方式中配置。</p></template>
          <template v-if="kind==='skills'"><section class="section"><h2>处理步骤</h2><EditableLines title="每行一个步骤" :model-value="stepLines" @update:model-value="content.steps=$event.filter(line=>line.trim())" /></section><section class="section"><h2>规则与计算口径</h2><StructuredRules :model-value="content.rules||[]" editable @update:model-value="content.rules=$event" /></section></template>
        </template>
        <ResourceOverview v-else :kind="kind" :content="visibleContent" :tasks="resourceTasks" />
        <template v-if="kind==='skills'"><section v-if="selected.policyDomains?.length" class="section"><h2>正式政策与条件规则</h2><RuleMaintenance :skill-id="selected.id" :allowed-domains="selected.policyDomains" /></section><section v-if="visibleContent.package" class="section"><h2>技能包 · {{ visibleContent.package.filename }}</h2><p>{{ visibleContent.package.frontMatter.description }}</p><details><summary>查看技能包文件</summary><details v-for="file in visibleContent.package.files" :key="file.path"><summary>{{ file.path }} · {{ file.size }} B</summary><pre>{{ file.text??'无文本内容' }}</pre></details></details></section><el-button :disabled="busy||dirty" @click="importTarget=selected;importVisible=true">更新技能包（新草稿）</el-button></template>
        <template v-if="kind==='mcps'"><section v-if="!editing" class="section"><h2>连接概览</h2><dl class="metadata"><dt>接入类型</dt><dd>{{ visibleContent.accessType==='native'?'原生MCP（仅登记）':visibleContent.accessType==='http'?'HTTP转换（仅登记）':'内部已登记工具' }}</dd><dt>连接方式</dt><dd>{{ transportLabel(visibleContent.transport) }}</dd><dt>服务地址</dt><dd><code>{{ visibleContent.accessType==='internal'||!visibleContent.accessType?visibleContent.endpoint||'由服务端配置':visibleContent.serviceUrl||'尚未填写' }}</code></dd><dt>凭据</dt><dd>由服务端保管，已保存值不返回浏览器。</dd><dt>查询范围</dt><dd>只读；每次调用重新校验当前工作身份与权限。</dd></dl><p v-if="visibleContent.accessType&&visibleContent.accessType!=='internal'" class="notice warning">外部执行尚未接入，当前仅登记配置，不能供技能运行。</p></section>
          <section class="section"><h2>工具清单 · {{ visibleContent.tools?.length||0 }} 个</h2><el-button v-if="editing" @click="editJson('tools','高级：工具 JSON 契约')">高级工具契约</el-button><p class="muted">{{ editing?'勾选此服务开放的已登记工具。':'查看工具用途与输入输出；修改工具范围请编辑草稿。' }}</p><details v-for="tool in toolsForDisplay" :key="tool.name" class="tool-item"><summary><el-checkbox v-if="editing&&(content.accessType==='internal'||!content.accessType)" :model-value="content.tools?.some(item=>item.name===tool.name)" @click.stop @update:model-value="checked=>chooseTool(tool,Boolean(checked))">{{ tool.title||tool.name }}</el-checkbox><b v-else>{{ tool.title||tool.name }}</b><code>{{ tool.name }}</code></summary><p>{{ tool.description }}</p><SchemaFields title="工具输入" :schema="tool.inputSchema" /><SchemaFields title="工具输出" :schema="tool.outputSchema" /></details></section></template>
      </div>
      <div v-if="section==='dependencies'">
        <template v-if="kind==='experts'"><section class="section"><div class="section-heading"><h2>绑定技能</h2><el-button v-if="!editing" :disabled="busy" @click="editBindings">修改技能绑定</el-button></div><p class="muted">专家绑定技能，MCP由技能自动带出。选择或取消技能后保存草稿；测试与发布后生效，现行版本和历史记录保留原依赖。</p><div v-if="editing" class="binding-toolbar"><el-input v-model="bindingSearch" clearable placeholder="搜索技能名称、编码或用途" aria-label="搜索可绑定技能" /><span>当前选择 {{ content.skillIds?.length||0 }} 项</span></div><div v-for="skill in editing?bindingChoices:visibleSkills" :key="skill.id" class="binding-row"><div><el-checkbox v-if="editing" :disabled="(!skill.published||!skill.enabled)&&!content.skillIds?.includes(skill.id)" :model-value="content.skillIds?.includes(skill.id)" @update:model-value="bindSkill(skill.id,Boolean($event))"><strong>{{ skill.name }}</strong></el-checkbox><b v-else>{{ skill.name }}</b><p>{{ skill.published?.content.summary||skill.summary }}</p><small>{{ dependencyVersion(skill) }}</small></div><el-button link @click="open(skill)">查看技能</el-button></div><p v-if="!visibleSkills.length&&!editing" class="muted">暂无绑定技能。</p></section><section v-if="editing||visibleContent.plannedSkillIds?.length" class="section"><h2>待建设技能</h2><p class="muted">仅登记计划，不作为当前运行能力。</p><el-select v-if="editing" v-model="content.plannedSkillIds" multiple clearable filterable placeholder="选择待建设技能"><el-option v-for="skill in catalog.skills" :key="skill.id" :label="skill.name" :value="skill.id" /></el-select><ul v-else class="detail-list"><li v-for="id in visibleContent.plannedSkillIds" :key="id">{{ catalog.skills.find(item=>item.id===id)?.name||id }}</li></ul></section><section class="section"><h2>经技能使用的MCP工具</h2><div v-for="binding in derivedTools" :key="`${binding.serverId}/${binding.toolName}`" class="dependency-row"><div><b>{{ mcpName(binding.serverId) }}</b><p>{{ toolTitle(binding.serverId,binding.toolName) }}</p></div><el-button link @click="openById('mcps',binding.serverId)">查看服务</el-button></div><p v-if="!derivedTools.length" class="muted">暂无工具依赖。</p></section></template>
        <template v-else-if="kind==='skills'"><div v-if="editing" class="button-row"><el-button @click="editJson('inputSchema','高级：输入参数 JSON 契约')">高级输入配置</el-button><el-button @click="editJson('outputSchema','高级：输出结果 JSON 契约')">高级输出配置</el-button></div><p class="muted">字段契约必须与已登记方法一致；展示条数不改变计算分母。</p><div class="schema-grid"><SchemaFields title="需要的输入" :schema="visibleContent.inputSchema" /><SchemaFields title="返回的结果" :schema="visibleContent.outputSchema" /></div><section class="section"><div class="section-heading"><h2>直接调用的MCP工具</h2><el-button v-if="!editing" :disabled="busy" @click="editBindings">修改工具关联</el-button></div><div v-if="editing" class="tool-bindings"><div v-for="(binding,index) in content.toolBindings||[]" :key="index" class="binding-controls"><el-select v-model="binding.serverId" placeholder="选择MCP服务" @change="binding.toolName='' "><el-option v-for="server in catalog.mcps.filter(item=>item.published&&item.enabled)" :key="server.id" :value="server.id" :label="server.name" /></el-select><el-select v-model="binding.toolName" placeholder="选择服务工具"><el-option v-for="tool in serverTools(binding.serverId)" :key="tool.name" :value="tool.name" :label="tool.title||tool.name" /></el-select><el-button @click="content.toolBindings?.splice(index,1)">移除</el-button></div><el-button @click="addToolBinding">添加工具关联</el-button></div><div v-else v-for="binding in visibleContent.toolBindings||[]" :key="`${binding.serverId}/${binding.toolName}`" class="dependency-row"><div><b>{{ mcpName(binding.serverId) }}</b><p>{{ toolTitle(binding.serverId,binding.toolName) }}</p></div><el-button link @click="openById('mcps',binding.serverId)">查看服务</el-button></div><p v-if="!visibleContent.toolBindings?.length" class="muted">暂无独立MCP依赖，实际执行以登记方法为准。</p></section></template>
        <section v-if="referenceGroups.length||kind==='mcps'||kind==='skills'" class="section"><h2>使用关系</h2><div v-for="reference in referenceGroups" :key="`${reference.kind}/${reference.id}`" class="dependency-row"><div><b>{{ reference.name }}</b><p>{{ kind==='mcps'?(reference.kind==='skills'?'技能直接调用':'专家经技能使用'):'专家绑定此技能' }}</p><div class="tags"><span v-for="relation in reference.versions" :key="relation">{{ relation }}</span></div></div><el-button link @click="openById(reference.kind,reference.id)">查看资源</el-button></div><p v-if="!referenceGroups.length" class="muted">暂无其他资源引用。</p><p class="muted">历史使用记录 {{ selected.references?.historyCount||0 }} 条；按版本保留，不因删除而清除。</p></section>
      </div>
      <PresetTasks v-if="section==='presets'&&kind==='experts'" :expert-id="selected.id" />
      <div v-if="section==='test'" class="test-layout"><section class="section test-form"><h2>{{ kind==='mcps'?'检查连接与工具':'测试当前草稿' }}</h2><p class="muted">草稿 v{{ selected.draft.version }} · 修订 {{ selected.draft.revision }}。当前身份：{{ authStore.user?.username||'当前工作身份' }}。</p><p class="muted">{{ kind==='mcps'?'仅验证连接和工具登记，业务结果由技能分别验证。':'使用当前身份的真实数据；测试记录与正式会话分开保存。' }}</p><div v-if="dirty" class="notice warning">请先保存草稿。</div><label v-if="kind==='experts'" class="field"><span>测试技能</span><el-select v-model="testSkillId" @change="testInput={}"><el-option v-for="skill in boundSkills" :key="skill.id" :value="skill.id" :label="skill.name" /></el-select></label><ScopeInputs v-if="kind!=='mcps'" v-model="testInput" :schema="testSchema" :options="options" :loading="optionsLoading" :failed="!!optionsError" /><p v-for="problem in testProblems" :key="problem" class="muted">{{ problem }}</p><p v-if="optionsError&&kind!=='mcps'" class="notice warning">{{ optionsError }}</p><el-button type="primary" :loading="testing" :disabled="dirty||busy||testProblems.length>0||(kind==='experts'&&!testSkillId)||externalOnly" @click="test">{{ kind==='mcps'?'执行连接检查':'运行测试' }}</el-button><p v-if="externalOnly" class="notice warning">此接入类型暂不可执行，不能运行连接检查。</p></section>
        <div><section v-if="selected.draft.test&&!selected.draft.test.redacted" class="section"><p class="muted">测试修订：{{ selected.draft.test.revision }} · {{ formatDate(selected.draft.test.createdAt) }}（北京时间）</p><div v-if="selected.draft.test.valid===false" class="notice warning">此记录已失效，不能用于当前发布，请重新测试。</div><RunResult :run="selected.draft.test" :options="options" :version="selected.draft.version" mode="test" /></section><section v-else class="section no-result"><h2>{{ selected.draft.test?.redacted?'需在当前身份重新测试':'尚无当前草稿测试结果' }}</h2><p>{{ selected.draft.test?.redacted?'已有记录属于其他工作身份或范围，不能用于当前核对与发布。':'运行后显示真实数据、来源、范围及执行过程。' }}</p></section>
          <section class="section"><h2>核对与发布</h2><div class="release-steps"><span>保存草稿</span><span>→</span><span>有效测试</span><template v-if="kind!=='mcps'"><span>→</span><span>业务核对</span></template><span>→</span><span>发布版本</span></div><template v-if="kind!=='mcps'"><label class="field"><span>本次测试核对说明</span><el-input v-model="reviewNote" type="textarea" :rows="2" placeholder="说明实际检查的记录、口径、范围和结果" /></label><div class="button-row"><el-button :disabled="!canReview||busy" @click="review(true)">记录核对通过</el-button><el-button :disabled="!canReview||busy" @click="review(false)">记录需修正</el-button></div><p v-if="selected.draft.review" class="muted">{{ currentReview?`本次测试核对：${selected.draft.review.accepted?'通过':'需修正'} · ${selected.draft.review.note}`:'已有核对不能用于当前修订或身份，请完成本次有效测试后重新核对。' }}</p></template><ul v-if="publishReasons.length" class="release-reasons"><li v-for="reason in publishReasons" :key="reason">{{ reason }}</li></ul><el-button v-if="selected.published?.version!==selected.draft.version" type="primary" :disabled="!canPublish||busy" :loading="publishing" @click="publish">发布 v{{ selected.draft.version }}</el-button><el-button v-else :disabled="busy||dirty" @click="newVersion">现行版本已发布 · 建立新版本草稿</el-button><p class="muted">新发布用于后续使用；历史会话保留原版本和结果。</p></section></div>
