const loading=ref(false),error=ref(''),optionsError=ref(''),optionsLoading=ref(false),kind=ref<ResourceKind>((route.meta.resourceKind as ResourceKind)||'experts'),search=ref(''),category=ref(''),status=ref('')
const navigation=ref<Array<{id:string;kind:ResourceKind;name:string;section:string}>>([])
const expanded=ref(false),bindingSearch=ref(''),createSnapshot=ref(''),importDialog=ref<InstanceType<typeof ImportSkillDialog>|null>(null)
const editing=ref(false),viewVersion=ref<'published'|'draft'>('published'),tasks=ref<BusinessTask[]>([])
