const saving=ref(false),testing=ref(false),publishing=ref(false),mutating=ref(false),testSkillId=ref(''),testInput=ref<Record<string,unknown>>({}),reviewNote=ref('')
const kinds:Array<{key:ResourceKind,label:string}>=[{key:'experts',label:'专家'},{key:'skills',label:'技能'},{key:'mcps',label:'MCP 服务'}]
