const filtered=computed(()=>catalog.value[kind.value].filter(item=>(!search.value||`${item.name} ${item.summary} ${item.id}`.toLowerCase().includes(search.value.toLowerCase()))&&(!category.value||item.category===category.value)&&(!status.value||(status.value==='published'?!!item.published:status.value==='disabled'?!item.enabled:!item.published))))
