const bindingNames=computed(()=>kind.value==='experts'?visibleSkills.value.map(item=>item.name):(visibleContent.value.toolBindings||[]).map(item=>`${mcpName(item.serverId)} / ${toolTitle(item.serverId,item.toolName)}`))
