const testProblems=computed(()=>kind.value==='mcps'?[]:inputProblems(testSchema.value,testInput.value))
const derivedTools=computed(()=>{const map=new Map<string,{serverId:string,toolName:string}>();for(const skill of visibleSkills.value)for(const tool of (skill.published?.content||skill.draft.content).toolBindings||[])map.set(`${tool.serverId}/${tool.toolName}`,tool);return [...map.values()]})
const skillUsers=computed(()=>catalog.value.experts.filter(item=>item.draft.content.skillIds?.includes(selected.value?.id||'')))
