const referenceGroups=computed(()=>{const groups=new Map<string,{kind:ResourceKind;id:string;name:string;versions:string[]}>();for(const reference of selected.value?.references?.items||[]){const key=reference.kind+'/'+reference.id,group=groups.get(key)||{kind:reference.kind,id:reference.id,name:reference.name,versions:[]};const label=`${reference.relation==='published'?'已发布':'草稿'}${reference.version?' v'+reference.version:''}`;if(!group.versions.includes(label))group.versions.push(label);groups.set(key,group)}return [...groups.values()]})
function dependencyVersion(skill:ExpertResource){const frozen=(selected.value?.published?.dependencies?.skills||[]).find((item:any)=>item.id===skill.id);return !editing.value&&viewVersion.value==='published'&&frozen?`固定 v${frozen.version}`:skill.published?`当前已发布 v${skill.published.version}${skill.enabled?'':' · 已停用'}`:'尚未发布'}
