function editBindings(){if(busy.value)return;startEdit();section.value='dependencies';bindingSearch.value=''}
async function cancelEdit(){if(!await mayLeave())return;content.value=JSON.parse(savedContent.value);editing.value=false}
async function newVersion(){await save();if(!error.value){editing.value=true;viewVersion.value='draft';section.value='basic'}}
async function detailAction(command:unknown){if(busy.value||dirty.value)return;if(command==='copy')startCreate(selected.value);else if(command==='new')await newVersion();else if(command==='toggle')await toggleEnabled();else if(command==='delete')await removeResource()}
