  const requestId=++optionsRequest
  optionsLoading.value=true
  optionsError.value=''
  try{
    const result=await api.options()
    if(requestId===optionsRequest)options.value=result
  }catch(e){
    if(requestId===optionsRequest)optionsError.value=`范围选项未加载：${(e as Error).message}`
  }finally{
    if(requestId===optionsRequest)optionsLoading.value=false
  }
