function apply(resource:ExpertResource){const wasEditing=editing.value;editing.value=false;viewVersion.value=wasEditing||!resource.published?'draft':'published';selected.value=resource;kind.value=resource.kind;content.value=JSON.parse(JSON.stringify(resource.draft.content));content.value.name??=resource.name;content.value.summary??=resource.summary;content.value.category??=resource.category;if(resource.kind==='experts'){content.value.executionMode??='deterministic';content.value.expertType??='single';content.value.maxIters??=200;content.value.sandboxEnabled??=false;content.value.personaPrompt??=''}if(resource.kind==='mcps'){content.value.accessType??='internal';content.value.serviceUrl??=content.value.endpoint||'';content.value.requestHeaders??=[];if(content.value.accessType==='http')content.value.httpConfig??={method:'GET',requestMapping:'',responseMapping:''}}savedContent.value=JSON.stringify(content.value);reviewNote.value=resource.draft.review?.note||'';const list=catalog.value[kind.value];const index=list.findIndex(item=>item.id===resource.id);if(index>=0)list[index]=resource;else list.push(resource);if(!content.value.skillIds?.includes(testSkillId.value))testSkillId.value=content.value.skillIds?.[0]||''}
