async function loadArchive(){if(!showArchived.value)return;loading.value=true;error.value='';try{archived.value=(await api.archived(kind.value)).items}catch(e){error.value=(e as Error).message}finally{loading.value=false}}
function startCreate(source?:ExpertResource|null){if(busy.value)return;if(kind.value==='skills'&&!source){importTarget.value=null;importVisible.value=true;return}createContent.value=source?JSON.parse(JSON.stringify(source.draft.content)):{executionMode:'deterministic',expertType:'single',maxIters:200,sandboxEnabled:false,skillIds:[],childExpertIds:[],accessType:'internal',transport:'internal',requestHeaders:[]};copySource.value=source||null;createForm.value={id:source?`${source.id}-copy`:'',name:source?`${source.name}（副本）`:'',category:source?.category||'',summary:source?.summary||'',templateId:''};createError.value='';createSnapshot.value=JSON.stringify({form:createForm.value,content:createContent.value});createVisible.value=true}
function createdPackage(resource:ExpertResource){navigation.value=[];showArchived.value=false;apply(resource);viewVersion.value='draft';section.value='basic';ElMessage.success('技能包已校验并保存为待接入草稿')}
async function createResource(){if(busy.value)return;mutating.value=true;createError.value='';try{let resource=copySource.value?await api.copy(kind.value,copySource.value.id,copySource.value.draft.revision,{id:createForm.value.id.trim()||undefined,name:createForm.value.name.trim()}):await api.create(kind.value,{...createForm.value,id:createForm.value.id.trim()||undefined,name:createForm.value.name.trim(),templateId:createForm.value.templateId||undefined,content:{...createContent.value,name:createForm.value.name.trim(),category:createForm.value.category,summary:createForm.value.summary}});if(copySource.value){createContent.value.id=resource.id;if(kind.value==='experts')createContent.value.expertCode=resource.id}if(copySource.value||resource.draft.content.category!==createForm.value.category||resource.draft.content.summary!==createForm.value.summary)resource=await api.save(kind.value,resource.id,resource.draft.revision,{...resource.draft.content,...createContent.value,category:createForm.value.category,summary:createForm.value.summary,name:createForm.value.name.trim()});createVisible.value=false;navigation.value=[];showArchived.value=false;apply(resource);section.value='basic';ElMessage.success('草稿已创建，请完成配置与测试')}catch(e){createError.value=(e as Error).message}finally{mutating.value=false}}
async function removeResource(){if(!selected.value||busy.value||dirty.value)return;error.value='';try{selected.value.references=await api.references(kind.value,selected.value.id);if(!selected.value.references.canDelete){section.value='dependencies';error.value='此资源仍被其他资源引用，请先解除下方关联后再删除。';return}await ElMessageBox.confirm('资源将移入已删除列表，可恢复。已发布版本与历史使用记录仍保留。','删除资源',{confirmButtonText:'删除',cancelButtonText:'取消',type:'warning'})}catch(e){if(e instanceof Error)error.value=e.message;return}mutating.value=true;try{await api.remove(kind.value,selected.value.id,selected.value.draft.revision);selected.value=null;navigation.value=[];await load();ElMessage.success('已移入已删除资源')}catch(e){error.value=(e as Error).message}finally{mutating.value=false}}
async function restoreResource(item:ExpertResource){if(busy.value)return;mutating.value=true;error.value='';try{await api.restore(kind.value,item.id,item.draft.revision);await loadArchive();await load();ElMessage.success('资源已恢复，请检查启用与发布状态')}catch(e){error.value=(e as Error).message}finally{mutating.value=false}}
let resourceRequest=0
async function showResource(item:ExpertResource,pushHistory=true){const request=++resourceRequest;loading.value=true;error.value='';try{const target=await api.resource(item.kind,item.id);if(request!==resourceRequest)return;if(selected.value&&pushHistory)navigation.value.push({id:selected.value.id,kind:kind.value,name:selected.value.name,section:section.value});apply(target);section.value='basic';testInput.value={}}catch(e){if(request===resourceRequest)error.value=(e as Error).message}finally{if(request===resourceRequest)loading.value=false}}
async function reloadSelected(){if(!selected.value||busy.value||!await mayLeave())return;const item=selected.value,previousSection=section.value;await load();await showResource(item,false);if(selected.value?.id===item.id)section.value=previousSection}
async function open(item:ExpertResource){if(busy.value)return;if(item.kind!==(route.meta.resourceKind as ResourceKind)){const backTo=selected.value?router.resolve({path:resourceRoutes[kind.value],query:{...route.query,resourceId:selected.value.id,section:section.value,search:search.value,category:category.value,status:status.value}}).fullPath:route.fullPath;await router.push({path:resourceRoutes[item.kind],query:{resourceId:item.id,backTo,backLabel:selected.value?.name||moduleTitle.value}});return}if(await mayLeave())await showResource(item)}
async function openById(resourceKind:ResourceKind,id:string){const item=catalog.value[resourceKind].find(item=>item.id===id);if(item)await open(item)}
const resourceRoutes:Record<ResourceKind,string>={experts:'/admin/system/expert-management',skills:'/admin/system/skill-management',mcps:'/admin/system/mcp-management'}
async function openRequestedResource(query:Record<string,unknown>){search.value=typeof query.search==='string'?query.search:'';category.value=typeof query.category==='string'?query.category:'';status.value=typeof query.status==='string'?query.status:'';const id=query.resourceId||query.expertId;if(typeof id!=='string'||!id)return;await openById(kind.value,id);if(selected.value?.id===id&&['basic','dependencies','test','presets'].includes(String(query.section)))section.value=String(query.section)}
async function back(){if(busy.value)return;if(typeof route.query.backTo==='string'&&route.query.backTo.startsWith('/admin/system/')){await router.push(route.query.backTo);return}if(!navigation.value.length&&(route.query.resourceId||route.query.expertId)){const query={...route.query};delete query.resourceId;delete query.expertId;delete query.section;await router.replace({path:route.path,query});return}if(!await mayLeave())return;error.value='';const previous=navigation.value[navigation.value.length-1];if(previous){loading.value=true;try{const resource=await api.resource(previous.kind,previous.id);navigation.value.pop();apply(resource);section.value=previous.section;testInput.value={}}catch(e){error.value=(e as Error).message}finally{loading.value=false}}else{selected.value=null;kind.value=(route.meta.resourceKind as ResourceKind)||'experts';await load()}}
function changeKind(next:ResourceKind){kind.value=next;category.value='';status.value='';search.value=''}
function bindSkill(id:string,checked:boolean){if(checked&&!catalog.value.skills.some(item=>item.id===id&&item.published&&item.enabled))return;const ids=new Set(content.value.skillIds||[]);checked?ids.add(id):ids.delete(id);content.value.skillIds=[...ids]}
async function save(){if(!selected.value||busy.value)return;if(!content.value.name?.trim()){error.value='请填写名称';return}saving.value=true;error.value='';try{apply(await api.save(kind.value,selected.value.id,selected.value.draft.revision,content.value));ElMessage.success('草稿已保存，测试和核对状态已按当前修订更新')}catch(e){error.value=(e as Error).message}finally{saving.value=false}}
async function test(){if(!selected.value||dirty.value||busy.value||testProblems.value.length)return;testing.value=true;error.value='';try{const input={...testInput.value,...(kind.value==='experts'?{skill_id:testSkillId.value}:{})};apply(await api.test(kind.value,selected.value.id,selected.value.draft.revision,input))}catch(e){error.value=(e as Error).message}finally{testing.value=false}}
async function review(accepted:boolean){if(!selected.value||!canReview.value)return;if(!reviewNote.value.trim()){ElMessage.warning('请填写本次业务核对说明');return}mutating.value=true;error.value='';try{apply(await api.review(kind.value,selected.value.id,selected.value.draft.revision,String(selected.value.draft.test?.runId||selected.value.draft.test?.id||''),accepted,reviewNote.value.trim()));ElMessage.success('核对意见已记录')}catch(e){error.value=(e as Error).message}finally{mutating.value=false}}
async function publish(){if(!selected.value||!canPublish.value)return;publishing.value=true;error.value='';try{apply(await api.publish(kind.value,selected.value.id,selected.value.draft.revision));ElMessage.success('版本已发布')}catch(e){error.value=(e as Error).message}finally{publishing.value=false}}
async function toggleEnabled(){if(!selected.value)return;try{await ElMessageBox.confirm(selected.value.enabled?'停用后，依赖此资源的新研究与测试将受到影响。已有记录仍可查看。':'启用后仍需满足发布、工具和数据条件，才能开展研究。',selected.value.enabled?'停用资源':'启用资源',{confirmButtonText:'确认',cancelButtonText:'取消'});}catch{return}mutating.value=true;error.value='';try{apply(await api.enabled(kind.value,selected.value.id,!selected.value.enabled))}catch(e){error.value=(e as Error).message}finally{mutating.value=false}}
watch(testSchema,schema=>{for(const [key,field] of Object.entries(schema?.properties||{}))if(field.default!=null&&testInput.value[key]==null)testInput.value[key]=field.default})
watch(()=>[authStore.user?.username,authStore.user?.activeIdentityId,authStore.user?.permissionContext?.scopeFingerprint].join('|'),()=>{createVisible.value=false;importVisible.value=false;jsonVisible.value=false;navigation.value=[];selected.value=null;catalog.value={experts:[],skills:[],mcps:[]};options.value={plans:[],semesters:[],colleges:[]};testInput.value={};error.value='';if(authStore.user){void load();void loadOptions()}})

onBeforeRouteUpdate(async()=>busy.value?false:await mayLeave())
onBeforeRouteLeave(async()=>busy.value?false:await mayLeave())
let routeRequest=0
async function syncRoute(){const request=++routeRequest;resourceRequest++;selected.value=null;navigation.value=[];kind.value=(route.meta.resourceKind as ResourceKind)||'experts';search.value='';category.value='';status.value='';showArchived.value=false;createVisible.value=false;importVisible.value=false;jsonVisible.value=false;await load();if(request===routeRequest)await openRequestedResource(route.query)}
// Sibling resource routes reuse this component without calling its update guard.
watch(()=>route.fullPath,()=>void syncRoute())
watch(()=>selected.value?.id,()=>{bindingSearch.value='';expanded.value=false})
watch(section,value=>{if(['test','presets'].includes(value)&&!options.value.queriedAt&&!optionsLoading.value)void loadOptions()})
onMounted(()=>void syncRoute())
</script>
